1	// Package indexroom implements chain ingestion with reorg handling.
2	package indexroom
3	
4	import "sync"
5	
6	// Block is one ingested block with its transactions.
7	type Block struct {
8		Height int64
9		Hash   string
10		Parent string
11		Txs    []string
12	}
13	
14	// Index is the durable chain view.
15	//
16	// Append and Reorg are safe for concurrent use; the exported fields are
17	// meant for read-only inspection after all calls have finished.
18	type Index struct {
19		Blocks map[int64]Block
20		ByHash map[string]int64
21		Tip    int64
22	
23		mu sync.Mutex
24	}
25	
26	// New returns an empty index.
27	func New() *Index { return &Index{Blocks: map[int64]Block{}, ByHash: map[string]int64{}} }
28	
29	// Append accepts a block only when it extends the current tip, keeping the
30	// chain linear. Re-submitting a block identical to one already on the main
31	// chain is a successful no-op. A rejected append leaves the index untouched.
32	func (index *Index) Append(block Block) error {
33		index.mu.Lock()
34		defer index.mu.Unlock()
35		return index.appendLocked(block)
36	}
37	
38	func (index *Index) appendLocked(block Block) error {
39		if block.Hash == "" {
40			return errInvalid("block needs a hash")
41		}
42		if index.Tip == 0 {
43			// Empty index: only the first block at height 1 is accepted; its
44			// parent becomes the chain start identifier and need not be indexed.
45			if block.Height != 1 {
46				return errInvalid("first block must be at height 1")
47			}
48			index.storeLocked(block)
49			return nil
50		}
51		if old, exists := index.Blocks[block.Height]; exists {
52			if sameBlock(old, block) {
53				return nil
54			}
55			return errInvalid("height already indexed with different content")
56		}
57		if block.Height != index.Tip+1 {
58			return errInvalid("block height must extend the current tip")
59		}
60		if block.Parent != index.Blocks[index.Tip].Hash {
61			return errInvalid("parent does not match the current tip")
62		}
63		if _, exists := index.ByHash[block.Hash]; exists {
64			return errInvalid("hash already indexed at another height")
65		}
66		index.storeLocked(block)
67		return nil
68	}
69	
70	// Reorg replaces the tip range with an alternate branch and reports the
71	// dropped old heights in ascending order. The branch is validated in full
72	// before anything is applied, so a rejected reorg leaves the index exactly
73	// as it was. Heights whose old block is identical to the new one are not
74	// reported; re-submitting the branch already in effect returns an empty list.
75	func (index *Index) Reorg(blocks []Block) ([]int64, error) {
76		index.mu.Lock()
77		defer index.mu.Unlock()
78	
79		if len(blocks) == 0 {
80			return nil, errInvalid("empty branch")
81		}
82		ancestor, ok := index.ByHash[blocks[0].Parent]
83		if !ok {
84			return nil, errInvalid("branch parent is unknown")
85		}
86		if blocks[0].Height != ancestor+1 {
87			return nil, errInvalid("branch must start at the ancestor height plus one")
88		}
89		seen := make(map[string]bool, len(blocks))
90		for i, block := range blocks {
91			if block.Hash == "" {
92				return nil, errInvalid("block needs a hash")
93			}
94			if seen[block.Hash] {
95				return nil, errInvalid("duplicate hash inside branch")
96			}
97			seen[block.Hash] = true
98			if height, exists := index.ByHash[block.Hash]; exists && height <= ancestor {
99				return nil, errInvalid("hash conflicts with a retained block")
100			}
101			if i > 0 {
102				prev := blocks[i-1]
103				if block.Height != prev.Height+1 {
104					return nil, errInvalid("branch heights must be consecutive")
105				}
106				if block.Parent != prev.Hash {
107					return nil, errInvalid("branch parent does not match the previous block")
108				}
109			}
110		}
111	
112		// Everything validated; compute the dropped heights before mutating.
113		newTip := blocks[len(blocks)-1].Height
114		dropped := []int64{}
115		for height := ancestor + 1; height <= index.Tip; height++ {
116			if height > newTip {
117				dropped = append(dropped, height)
118				continue
119			}
120			if !sameBlock(index.Blocks[height], blocks[height-blocks[0].Height]) {
121				dropped = append(dropped, height)
122			}
123		}
124		for height := ancestor + 1; height <= index.Tip; height++ {
125			delete(index.ByHash, index.Blocks[height].Hash)
126			delete(index.Blocks, height)
127		}
128		index.Tip = ancestor
129		for _, block := range blocks {
130			index.storeLocked(block)
131		}
132		return dropped, nil
133	}
134	
135	// storeLocked records a validated block, copying its transactions so later
136	// caller-side mutation of the slice cannot alter the stored block.
137	func (index *Index) storeLocked(block Block) {
138		if block.Txs != nil {
139			txs := make([]string, len(block.Txs))
140			copy(txs, block.Txs)
141			block.Txs = txs
142		}
143		index.Blocks[block.Height] = block
144		index.ByHash[block.Hash] = block.Height
145		index.Tip = block.Height
146	}
147	
148	// sameBlock reports whether two blocks are identical: same height, hash,
149	// parent, and transactions in order. An empty tx list equals a missing one.
150	func sameBlock(a, b Block) bool {
151		if a.Height != b.Height || a.Hash != b.Hash || a.Parent != b.Parent {
152			return false
153		}
154		if len(a.Txs) != len(b.Txs) {
155			return false
156		}
157		for i := range a.Txs {
158			if a.Txs[i] != b.Txs[i] {
159				return false
160			}
161		}
162		return true
163	}
164	
165	type errInvalid string
166	
167	func (e errInvalid) Error() string { return string(e) }
168

