1	package indexroom
2	
3	import (
4		"fmt"
5		"reflect"
6		"sync"
7		"testing"
8	)
9	
10	func chain(t *testing.T, blocks ...Block) *Index {
11		t.Helper()
12		index := New()
13		for _, block := range blocks {
14			if err := index.Append(block); err != nil {
15				t.Fatalf("setup append at height %d: %v", block.Height, err)
16			}
17		}
18		return index
19	}
20	
21	func snapshot(index *Index) (map[int64]Block, map[string]int64, int64) {
22		blocks := make(map[int64]Block, len(index.Blocks))
23		for height, block := range index.Blocks {
24			blocks[height] = block
25		}
26		byHash := make(map[string]int64, len(index.ByHash))
27		for hash, height := range index.ByHash {
28			byHash[hash] = height
29		}
30		return blocks, byHash, index.Tip
31	}
32	
33	func requireUnchanged(t *testing.T, index *Index, blocks map[int64]Block, byHash map[string]int64, tip int64) {
34		t.Helper()
35		if !reflect.DeepEqual(index.Blocks, blocks) {
36			t.Fatalf("blocks changed after rejected call: got %v want %v", index.Blocks, blocks)
37		}
38		if !reflect.DeepEqual(index.ByHash, byHash) {
39			t.Fatalf("by-hash changed after rejected call: got %v want %v", index.ByHash, byHash)
40		}
41		if index.Tip != tip {
42			t.Fatalf("tip changed after rejected call: got %d want %d", index.Tip, tip)
43		}
44	}
45	
46	func TestAppendFirstBlockMustBeHeightOne(t *testing.T) {
47		index := New()
48		if err := index.Append(Block{Height: 2, Hash: "h2", Parent: "h1"}); err == nil {
49			t.Fatal("expected refusal of height jump on empty index")
50		}
51		if err := index.Append(Block{Height: 1, Hash: "h1", Parent: "genesis"}); err != nil {
52			t.Fatalf("first block refused: %v", err)
53		}
54		if index.Tip != 1 || index.ByHash["h1"] != 1 {
55			t.Fatalf("unexpected state: tip=%d byHash=%v", index.Tip, index.ByHash)
56		}
57	}
58	
59	func TestAppendRequiresContiguousTip(t *testing.T) {
60		index := chain(t,
61			Block{Height: 1, Hash: "h1", Parent: "genesis"},
62			Block{Height: 2, Hash: "h2", Parent: "h1"},
63		)
64		blocks, byHash, tip := snapshot(index)
65		for name, block := range map[string]Block{
66			"height jump":      {Height: 4, Hash: "h4", Parent: "h2"},
67			"wrong parent":     {Height: 3, Hash: "h3", Parent: "h1"},
68			"empty hash":       {Height: 3, Hash: "", Parent: "h2"},
69			"duplicate hash":   {Height: 3, Hash: "h1", Parent: "h2"},
70			"backwards height": {Height: 1, Hash: "h1b", Parent: "genesis"},
71		} {
72			if err := index.Append(block); err == nil {
73				t.Fatalf("expected refusal of %s", name)
74			}
75		}
76		requireUnchanged(t, index, blocks, byHash, tip)
77	}
78	
79	func TestAppendIdenticalReplayIsNoOp(t *testing.T) {
80		index := chain(t,
81			Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"t1"}},
82			Block{Height: 2, Hash: "h2", Parent: "h1"},
83		)
84		// Empty tx list and missing tx list are the same block.
85		if err := index.Append(Block{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{}}); err != nil {
86			t.Fatalf("identical replay refused: %v", err)
87		}
88		if err := index.Append(Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"t1"}}); err != nil {
89			t.Fatalf("identical replay of older block refused: %v", err)
90		}
91		if index.Tip != 2 {
92			t.Fatalf("tip moved on replay: %d", index.Tip)
93		}
94		// Same height or hash but different content must fail without overwrite.
95		for _, block := range []Block{
96			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"t9"}},
97			{Height: 2, Hash: "h2x", Parent: "h1"},
98			{Height: 1, Hash: "h1", Parent: "other"},
99		} {
100			blocks, byHash, tip := snapshot(index)
101			if err := index.Append(block); err == nil {
102				t.Fatalf("expected refusal of conflicting block %+v", block)
103			}
104			requireUnchanged(t, index, blocks, byHash, tip)
105		}
106		if got := index.Blocks[2]; got.Hash != "h2" || got.Txs != nil {
107			t.Fatalf("stored block overwritten: %+v", got)
108		}
109	}
110	
111	func TestAppendStoresCopyOfTxs(t *testing.T) {
112		index := New()
113		txs := []string{"t1", "t2"}
114		if err := index.Append(Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: txs}); err != nil {
115			t.Fatal(err)
116		}
117		txs[0] = "mutated"
118		if got := index.Blocks[1].Txs; !reflect.DeepEqual(got, []string{"t1", "t2"}) {
119			t.Fatalf("stored txs changed by caller mutation: %v", got)
120		}
121	}
122	
123	func TestReorgReplacesSuffixAndReportsDropped(t *testing.T) {
124		index := chain(t,
125			Block{Height: 1, Hash: "h1", Parent: "genesis"},
126			Block{Height: 2, Hash: "h2", Parent: "h1"},
127			Block{Height: 3, Hash: "h3", Parent: "h2"},
128		)
129		dropped, err := index.Reorg([]Block{
130			{Height: 2, Hash: "h2b", Parent: "h1"},
131			{Height: 3, Hash: "h3b", Parent: "h2b"},
132			{Height: 4, Hash: "h4b", Parent: "h3b"},
133		})
134		if err != nil {
135			t.Fatalf("reorg refused: %v", err)
136		}
137		if !reflect.DeepEqual(dropped, []int64{2, 3}) {
138			t.Fatalf("dropped=%v, want [2 3]", dropped)
139		}
140		if index.Tip != 4 {
141			t.Fatalf("tip=%d, want 4", index.Tip)
142		}
143		for _, hash := range []string{"h2", "h3"} {
144			if _, ok := index.ByHash[hash]; ok {
145				t.Fatalf("removed hash %s still indexed", hash)
146			}
147		}
148		if block, ok := index.Blocks[2]; !ok || block.Hash != "h2b" {
149			t.Fatalf("height 2 not replaced: %+v", index.Blocks[2])
150		}
151	}
152	
153	func TestReorgShorterBranchTruncates(t *testing.T) {
154		index := chain(t,
155			Block{Height: 1, Hash: "h1", Parent: "genesis"},
156			Block{Height: 2, Hash: "h2", Parent: "h1"},
157			Block{Height: 3, Hash: "h3", Parent: "h2"},
158		)
159		dropped, err := index.Reorg([]Block{{Height: 3, Hash: "h3b", Parent: "h2"}})
160		if err != nil {
161			t.Fatalf("reorg refused: %v", err)
162		}
163		if !reflect.DeepEqual(dropped, []int64{3}) {
164			t.Fatalf("dropped=%v, want [3]", dropped)
165		}
166		if index.Tip != 3 || index.Blocks[3].Hash != "h3b" {
167			t.Fatalf("unexpected tip state: tip=%d block=%+v", index.Tip, index.Blocks[3])
168		}
169		if _, ok := index.ByHash["h3"]; ok {
170			t.Fatal("old hash h3 still indexed")
171		}
172	}
173	
174	func TestReorgIdenticalBlocksNotReported(t *testing.T) {
175		index := chain(t,
176			Block{Height: 1, Hash: "h1", Parent: "genesis"},
177			Block{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"t1"}},
178			Block{Height: 3, Hash: "h3", Parent: "h2"},
179		)
180		// Height 2 is identical to the stored block (nil vs empty txs), only 3 differs.
181		dropped, err := index.Reorg([]Block{
182			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"t1"}},
183			{Height: 3, Hash: "h3b", Parent: "h2"},
184		})
185		if err != nil {
186			t.Fatalf("reorg refused: %v", err)
187		}
188		if !reflect.DeepEqual(dropped, []int64{3}) {
189			t.Fatalf("dropped=%v, want [3]", dropped)
190		}
191		// Re-submitting the branch now in effect succeeds with an empty list.
192		dropped, err = index.Reorg([]Block{
193			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"t1"}},
194			{Height: 3, Hash: "h3b", Parent: "h2"},
195		})
196		if err != nil {
197			t.Fatalf("idempotent reorg refused: %v", err)
198		}
199		if len(dropped) != 0 {
200			t.Fatalf("dropped=%v, want empty", dropped)
201		}
202		if index.Tip != 3 {
203			t.Fatalf("tip=%d, want 3", index.Tip)
204		}
205	}
206	
207	func TestReorgFailureLeavesStateUntouched(t *testing.T) {
208		build := func(t *testing.T) *Index {
209			return chain(t,
210				Block{Height: 1, Hash: "h1", Parent: "genesis"},
211				Block{Height: 2, Hash: "h2", Parent: "h1"},
212				Block{Height: 3, Hash: "h3", Parent: "h2"},
213			)
214		}
215		cases := map[string][]Block{
216			"empty branch":        {},
217			"unknown ancestor":    {{Height: 4, Hash: "h4", Parent: "nope"}},
218			"bad first height":    {{Height: 3, Hash: "h3b", Parent: "h1"}},
219			"gap inside branch":   {{Height: 2, Hash: "h2b", Parent: "h1"}, {Height: 4, Hash: "h4b", Parent: "h2b"}},
220			"bad parent inside":   {{Height: 2, Hash: "h2b", Parent: "h1"}, {Height: 3, Hash: "h3b", Parent: "h1"}},
221			"empty hash":          {{Height: 2, Hash: "h2b", Parent: "h1"}, {Height: 3, Hash: "", Parent: "h2b"}},
222			"duplicate in branch": {{Height: 2, Hash: "h2b", Parent: "h1"}, {Height: 3, Hash: "h2b", Parent: "h2b"}},
223			"conflict retained":   {{Height: 2, Hash: "h1", Parent: "h1"}},
224			// Error at the very end of the branch: nothing may be applied early.
225			"late error": {{Height: 2, Hash: "h2b", Parent: "h1"}, {Height: 3, Hash: "h3b", Parent: "h2b"}, {Height: 5, Hash: "h5b", Parent: "h3b"}},
226		}
227		for name, branch := range cases {
228			t.Run(name, func(t *testing.T) {
229				index := build(t)
230				blocks, byHash, tip := snapshot(index)
231				dropped, err := index.Reorg(branch)
232				if err == nil {
233					t.Fatal("expected reorg refusal")
234				}
235				if len(dropped) != 0 {
236					t.Fatalf("dropped=%v, want empty on error", dropped)
237				}
238				requireUnchanged(t, index, blocks, byHash, tip)
239			})
240		}
241	}
242	
243	func TestReorgRemovedSuffixHashesMayReappear(t *testing.T) {
244		index := chain(t,
245			Block{Height: 1, Hash: "h1", Parent: "genesis"},
246			Block{Height: 2, Hash: "h2", Parent: "h1"},
247			Block{Height: 3, Hash: "h3", Parent: "h2"},
248		)
249		// h3 lives in the removed suffix, so it may be reused at a new height.
250		dropped, err := index.Reorg([]Block{
251			{Height: 2, Hash: "h2b", Parent: "h1"},
252			{Height: 3, Hash: "h3", Parent: "h2b"},
253		})
254		if err != nil {
255			t.Fatalf("reorg refused: %v", err)
256		}
257		if !reflect.DeepEqual(dropped, []int64{2, 3}) {
258			t.Fatalf("dropped=%v, want [2 3]", dropped)
259		}
260		if index.ByHash["h3"] != 3 {
261			t.Fatalf("h3 not re-indexed: %v", index.ByHash)
262		}
263	}
264	
265	func TestReorgFailureThenCorrectedRetry(t *testing.T) {
266		index := chain(t,
267			Block{Height: 1, Hash: "h1", Parent: "genesis"},
268			Block{Height: 2, Hash: "h2", Parent: "h1"},
269		)
270		if _, err := index.Reorg([]Block{{Height: 2, Hash: "h2b", Parent: "unknown"}}); err == nil {
271			t.Fatal("expected refusal of unknown ancestor")
